const cmp=(title,scene,states,prompt,choices,answers,results,why)=>({type:'compare',title,scene,states,prompt,choices,answers,results,why});
export const reflexRoute=['receptor','sensory','synapse-in','relay','synapse-out','motor','effector'];
export const reflexLabels=['Receptor','Sensory neurone','Synapse 1','Relay neurone','Synapse 2','Motor neurone','Effector'];
export const reflexPoints=[[-1.9,.9,0],[-.9,.9,0],[-.2,.7,0],[.4,.3,0],[.15,-.3,0],[-.9,-.8,0],[-1.9,-.8,0]];
export const advanceReflex=(step,action)=>Number.isInteger(step)&&step>=0&&step<reflexRoute.length&&action===reflexRoute[step]?step+1:step;
export function synapseState({step=0,release=true,receptor=true}={}){let n=Math.max(0,Math.min(5,Math.floor(Number(step)||0)));return{step:n,transmitter:n>=2&&release,bound:n>=4&&release&&receptor,nextImpulse:n>=5&&release&&receptor};}
export const rulerScale=[[10,143],[15,175],[20,202],[25,226]];
export const reactionTrials={quiet:[175,165,170],distraction:[210,200,220]};
export const meanNeural=a=>Array.isArray(a)&&a.length&&a.every(Number.isFinite)?a.reduce((s,x)=>s+x,0)/a.length:null;
export const corrective=(value,target=5)=>value>target?'down':value<target?'up':'hold';
